const RECUR_MARK = /(?<![a-zäöüß])(?:obwohl|trotz|trotzdem|dennoch|erneut|nochmal|noch\s+mal|schon\s+wieder|immer\s+noch|weiterhin|wieder\s+(?:kaputt|defekt|undicht|da|los|lose|locker|aufgetreten|nicht|das\s+gleiche|dasselbe|gleich)|nach\s+(?:der\s+|dem\s+|einer\s+)?(?:reparatur|tausch|wechsel)\S*\s+(?:\S+\s+){0,3}?wieder(?!\s+(?:ok|okay|in\s+ordnung|gut|funktionsf\S*|fahrbereit|dicht|heil|fest|frei))|although|though|despite|still(?!\s+(?:fine|ok|okay|good|works?|working))|(?<!(?<!(?:not|n['’]t)\s+)(?:works?|working|fine|ok|okay|good|running|normal)\s+)again)(?![a-zäöüß])|(?<![а-яіїєґё])(?:хоча|хоч|попри|досі|хотя|несмотря|вс[её]\s+ещ[её]|все\s+ещ[её]|все\s+еще|(?<!(?:працює|работает)\s+)(?:знову|знов|опять|снова)(?!\s+(?:працює|работает)))(?![а-яіїєґё])/i;
const FIX_NEG = /(?:(?<![a-zäöüß])(?:nicht|nie|kein\S*|not|never)|n['’]t|(?<![а-яіїєґё])(?:не|ни))\s+(?:[a-zäöüßа-яіїєґё'’]+\s+){0,2}$/i;
// Backlog 764: geplante/geforderte Reparatur („muss getauscht werden“, „wird morgen repariert“, „needs to be replaced“, „will be fixed“,
// „треба замінити“, „нужно отремонтировать“) ist kein Reparaturvermerk – Infinitive (-ти/-ть) und Modalverben davor bzw. „werden/lassen“ danach.
const FIX_PLAN = /(?:(?<![a-zäöüß])(?:muss|m(?:ü|ue)ssen|soll(?:te|en)?|wird|bitte)|(?<![a-z])(?:be|needs?|must|should|will))\s+(?:[a-zäöüß]+\s+){0,2}$/i;
const FIX_PLAN_AFTER = /^\s+(?:werden|lassen)(?![a-zäöüß])/i;
// Backlog 769: EN „stopped/quit/ceased working“ wird wie „not working“ gelesen (Fenster, Navi, Spiegel, Sitz, Maut, Zentralverriegelung … kannten nur „not working“).
const STOP_WORK = /(?<![a-z])(?:stopp(?:ed|s)|quit(?:s|ted)?|ceased?)\s+(?:working|functioning)(?![a-z])/gi;
// Backlog 772: UK/RU mit vorangestelltem Prädikat („не працює кондиціонер“, „не работает автономка“, „не працюють двірники“; Backlog 1136 auch „не тримає ручник“,
// „не відкриваються двері“, „не открывается дверь“) – der Gegenstand (1–4 Wörter bis
// Satzzeichen/Präposition/Bindewort) wird hinter einem Trenner (⁘, kein Satzende) zusätzlich in Normalstellung angehängt („… ⁘ кондиціонер не працює“).
const PRED_FIRST = /(?<![а-яіїєґё])(не\s+(?:працю[а-яіїєґ]*|работа[а-яё]*|функціону[а-яіїєґ]*|функциониру[а-яё]*|трима[а-яіїєґ]*|держ[а-яё]*|відкрива[а-яіїєґ]*|закрива[а-яіїєґ]*|открыва[а-яё]*|закрыва[а-яё]*|підніма[а-яіїєґ]*|підійма[а-яіїєґ]*|поднима[а-яё]*|опуска[а-яіїєґё]*|відкида[а-яіїєґ]*|откидыва[а-яё]*|бризка[а-яіїєґ]*|брызга[а-яё]*|запуска[а-яіїєґё]*|гріють?|гріє|греє|греют?|греет|охолоджу[а-яіїєґ]*|охлажда[а-яё]*|спрацьову[а-яіїєґ]*|срабатыва[а-яё]*|заряджа[а-яіїєґ]*|заряжа[а-яё]*|вимика[а-яіїєґ]*|выключа[а-яё]*|дує|дме|дует|регулю[а-яіїєґ]*|регулиру[а-яё]*|застіба[а-яіїєґ]*|застеги[а-яё]*|пристіба[а-яіїєґ]*|пристеги[а-яё]*|зупиня[а-яіїєґ]*|останавлива[а-яё]*))((?:\s+[^\s.,;!?:()]+){1,4}?)(?=\s*(?:$|[.,;!?:()\n])|\s+(?:і|й|та|и|а|але|но|бо|тому|потому|після|после|з|із|зі|с|со|вже|уже|ще|еще|ещ[её]|в|у|на|при|під|под|від|от|до|коли|когда|хоча|хотя|знову|снова|опять)(?![а-яіїєґё]))/gi;
// Backlog 773: Werkstatt-/Formularsprache „ohne Funktion“, „keine Funktion“, „funktionslos“, „tut (es) nicht (mehr)“, „ohne/kein Bild“, „Klimaanlage: geht nicht“,
