  for (let i = 0; i < s.length; i++) { const c = s[i]; if (c === '\\') { i++; continue; } if (cls) { if (c === ']') cls = false; continue; } if (c === '[') cls = true; else if (c === '(') d++; else if (c === ')') d--; else if (c === '|' && !d) { top.push(s.slice(st, i)); st = i + 1; } }
  top.push(s.slice(st));
