fastHint(ENGINE_HINT); fastHint(NOSTART_HINT); fastHint(DOOR_HINT); fastHint(BRAKE_HINT); fastHint(TYRE_HINT); fastHint(GEAR_HINT); fastHint(WHEEL_HINT); fastHint(SUSP_HINT); fastHint(CABLEAK_HINT); fastHint(STEER_HINT); fastHint(LIGHTS_HINT); fastHint(TARP_HINT); fastHint(LEAK_HINT); fastHint(VISIB_HINT); fastHint(WARNLIGHT_HINT); fastHint(REEFER_HINT);
