  render(html, 'more');
  S.drvAt = Date.now();
  { const rl = $('#drvreload'); if (rl) rl.onclick = async (e) => { e.preventDefault(); try { await viewDrivers(); } catch (err) { toast(err.message, true); } }; }
  S.dtbRes = ''; S.dlbRes = ''; wireDtb(); wireDlb();
